using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace Praveen.XrmToolbox.P7mAttachmentConverter
{
    // This is what makes XrmToolBox discover the plugin and list it in the tool picker.
    // Description/BackgroundColor drive how the tile looks in the XrmToolBox UI.
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "P7M Attachment Converter"),
     ExportMetadata("Description", "Finds .p7m (PKCS#7/S-MIME) attachments on Dynamics 365 records and converts them back to their original readable file."),
     ExportMetadata("SmallImageBase64", ""),   // optional: base64 16x16 png
     ExportMetadata("BigImageBase64", ""),     // optional: base64 32x32 png
     ExportMetadata("BackgroundColor", "White"),
     ExportMetadata("PrimaryFontColor", "Black"),
     ExportMetadata("SecondaryFontColor", "DimGray")]
    public class P7mConverterPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new P7mConverterControl();
        }
    }
}
